public static void main(String[] args) {
    test("runs up to maxConcurrent tasks", () -> {
        var b = new Bulkhead(2, 1);
        eq(b.submit("t1"), Admission.RUNNING);
        eq(b.submit("t2"), Admission.RUNNING);
        eq(b.running(), List.of("t1", "t2"));
    });
    test("then queues up to maxQueue, then rejects", () -> {
        var b = new Bulkhead(1, 2);
        b.submit("t1");
        eq(b.submit("t2"), Admission.QUEUED);
        eq(b.submit("t3"), Admission.QUEUED);
        eq(b.submit("t4"), Admission.REJECTED);
        eq(b.queued(), List.of("t2", "t3"));
    });
    test("finishing promotes the oldest waiter", () -> {
        var b = new Bulkhead(1, 2);
        b.submit("t1");
        b.submit("t2");
        b.submit("t3");
        eq(b.finish("t1"), Optional.of("t2"));
        eq(b.running(), List.of("t2"));
        eq(b.queued(), List.of("t3"));
    });
    test("finishing with nobody waiting frees a permit", () -> {
        var b = new Bulkhead(2, 1);
        b.submit("t2");
        b.submit("t3");
        eq(b.finish("t2"), Optional.empty());
        eq(b.submit("t1"), Admission.RUNNING);
        eq(b.running(), List.of("t3", "t1"));
    });
    test("cancelling a queued task promotes nobody", () -> {
        var b = new Bulkhead(1, 2);
        b.submit("t1");
        b.submit("t2");
        b.submit("t3");
        eq(b.finish("t3"), Optional.empty());
        eq(b.running(), List.of("t1"));
        eq(b.queued(), List.of("t2"));
        eq(b.submit("t4"), Admission.QUEUED);
    });
    test("a rejected task is not remembered", () -> {
        var b = new Bulkhead(1, 0);
        b.submit("t1");
        eq(b.submit("t2"), Admission.REJECTED);
        raises(IllegalArgumentException.class, () -> b.finish("t2"));
        b.finish("t1");
        eq(b.submit("t2"), Admission.RUNNING);
    });
    test("refuses duplicate and unknown task ids", () -> {
        var b = new Bulkhead(1, 1);
        b.submit("t1");
        b.submit("t2");
        raises(IllegalArgumentException.class, () -> b.submit("t1"));
        raises(IllegalArgumentException.class, () -> b.submit("t2"));
        raises(IllegalArgumentException.class, () -> b.finish("nope"));
        eq(b.queued(), List.of("t2"));
    });
    test("refuses bad settings, but a zero queue is fine", () -> {
        raises(IllegalArgumentException.class, () -> new Bulkhead(0, 1));
        raises(IllegalArgumentException.class, () -> new Bulkhead(1, -1));
        eq(new Bulkhead(1, 0).submit("t1"), Admission.RUNNING);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("remaining counts down and never goes negative", () -> {
        var clock = new FakeClock();
        var d = Deadline.after(clock, 1_000);
        eq(d.remaining(), 1_000);
        clock.advance(300);
        eq(d.remaining(), 700);
        clock.advance(5_000);
        eq(d.remaining(), 0);
    });
    test("expired exactly when the budget is used up", () -> {
        var clock = new FakeClock();
        var d = Deadline.after(clock, 1_000);
        clock.advance(999);
        eq(d.expired(), false);
        clock.advance(1);
        eq(d.expired(), true);
        eq(Deadline.after(clock, 0).expired(), true);
        raises(IllegalArgumentException.class, () -> Deadline.after(clock, -1));
    });
    test("timeoutFor is the smaller of the call's timeout and the time left", () -> {
        var clock = new FakeClock();
        var d = Deadline.after(clock, 1_000);
        eq(d.timeoutFor(200), 200);
        clock.advance(900);
        eq(d.timeoutFor(200), 100);
        clock.advance(100);
        eq(d.timeoutFor(200), 0);
    });
    test("a child deadline is never looser than its parent", () -> {
        var clock = new FakeClock();
        var parent = Deadline.after(clock, 500);
        eq(parent.child(1_000).remaining(), 500);
        eq(parent.child(200).remaining(), 200);
        clock.advance(400);
        eq(parent.child(200).remaining(), 100);
    });
    test("a chain that fits runs every step and spends its cost", () -> {
        var clock = new FakeClock();
        var d = Deadline.after(clock, 1_000);
        var log = runChain(d, clock, List.of(new Step("auth", 50, 100), new Step("db", 300, 500)));
        eq(log, List.of("ok auth", "ok db"));
        eq(clock.now, 350);
    });
    test("a slow step times out at its own timeout and the chain goes on", () -> {
        var clock = new FakeClock();
        var d = Deadline.after(clock, 1_000);
        var log = runChain(d, clock, List.of(new Step("search", 900, 200), new Step("ads", 100, 300)));
        eq(log, List.of("timeout search", "ok ads"));
        eq(clock.now, 300);
    });
    test("the deadline caps a step; later steps are skipped for free", () -> {
        var clock = new FakeClock();
        var d = Deadline.after(clock, 1_000);
        var log = runChain(d, clock, List.of(
            new Step("a", 700, 800), new Step("b", 500, 800), new Step("c", 10, 800)));
        eq(log, List.of("ok a", "timeout b", "skipped c"));
        eq(clock.now, 1_000);
    });
    test("a step costing exactly its timeout succeeds", () -> {
        var clock = new FakeClock();
        var d = Deadline.after(clock, 300);
        eq(runChain(d, clock, List.of(new Step("a", 100, 100), new Step("b", 200, 500))),
            List.of("ok a", "ok b"));
        eq(d.expired(), true);
    });
    test("the header carries the time left, not the clock", () -> {
        var client = new FakeClock();
        var d = Deadline.after(client, 1_000);
        client.advance(300);
        eq(d.header(), "grpc-timeout: 700m");
        var server = new FakeClock();
        server.now = 5_000;
        var there = Deadline.fromHeader(server, d.header());
        eq(there.remaining(), 700);
        server.advance(700);
        eq(there.expired(), true);
        raises(IllegalArgumentException.class, () -> Deadline.fromHeader(server, "grpc-timeout: soon"));
        raises(IllegalArgumentException.class, () -> Deadline.fromHeader(server, "700m"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

