            raises(IllegalArgumentException.class, () -> new Retry(3, 0, 1_000, d -> d, ms -> { }));
            raises(IllegalArgumentException.class, () -> new Retry(3, 500, 100, d -> d, ms -> { }));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

