            var op = new Flaky(1, n -> new IllegalArgumentException("bad request"));
            raises(IllegalArgumentException.class, () -> retry.call(op, ON_TIMEOUT), "bad request");
            eq(op.attempts, 1);
            eq(sleeps, List.of());
        });
        test("backoff doubles up to the cap and never overflows", () -> {
